// torch-checkpoint-bridge.js
/* Native synchronous DCP bridge. Generated data are refreshed by build-torch-checkpoint.py. */
/* BEGIN TORCH CHECKPOINT GENERATED */
const torchCheckpointFiles = {"train_dcp.py": "\"\"\"DCP 2.5.1 / two CPU ranks, using the existing DDP lesson's exact workload.\n\nOnly complete epoch boundaries and a fixed world size are supported. The\nreference_train.py copy retains the original rank-0 torch.save baseline.\n\"\"\"\nimport argparse\nfrom contextlib import nullcontext\nfrom datetime import timedelta\nimport json\nimport os\nfrom pathlib import Path\n\nimport torch\nfrom torch import nn\nimport torch.distributed as dist\nimport torch.distributed.checkpoint as dcp\nfrom torch.distributed.checkpoint.state_dict import get_state_dict, set_state_dict\nfrom torch.distributed.checkpoint.stateful import Stateful\nfrom torch.nn.parallel import DistributedDataParallel as DDP\nfrom torch.utils.data import DataLoader, DistributedSampler, TensorDataset\n\n\nclass TrainState(Stateful):\n    def __init__(self, model, optimizer, loader_rng, signature, weights_only=False):\n        self.model, self.optimizer = model, optimizer\n        self.loader_rng, self.signature = loader_rng, signature\n        self.progress = {\"next_epoch\": 0, \"updates\": 0}\n        self.weights_only = weights_only\n        self.loaded = False\n\n    def rng_states(self):\n        local = {\"cpu\": torch.get_rng_state(), \"loader\": self.loader_rng.get_state()}\n        states = [None] * dist.get_world_size()\n        dist.all_gather_object(states, local)\n        return states\n\n    def state_dict(self):\n        # DCP calls this on save AND before load to allocate the destination tree.\n        model, optim = get_state_dict(self.model, self.optimizer)\n        return {\"model\": model, \"optim\": optim, \"progress\": self.progress.copy(),\n                \"signature\": self.signature.copy(), \"rng_by_rank\": self.rng_states()}\n\n    def load_state_dict(self, state):\n        if state[\"signature\"] != self.signature:\n            raise ValueError(\"fixed_configuration_required\")\n        if self.weights_only:\n            # Deliberate negative control: preserve input/RNG boundary but reset Adam.\n            self.model.module.load_state_dict(state[\"model\"])\n            self.optimizer.state.clear()\n        else:\n            set_state_dict(self.model, self.optimizer,\n                           model_state_dict=state[\"model\"], optim_state_dict=state[\"optim\"])\n        self.progress = dict(state[\"progress\"])\n        rng = state[\"rng_by_rank\"][dist.get_rank()]\n        torch.set_rng_state(rng[\"cpu\"])\n        self.loader_rng.set_state(rng[\"loader\"])\n        self.loaded = True\n\n\ndef main():\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument(\"--epochs\", type=int, required=True, help=\"Total target epochs\")\n    p.add_argument(\"--output\", type=Path, required=True)\n    p.add_argument(\"--resume\", type=Path)\n    p.add_argument(\"--weights-only\", action=\"store_true\")\n    args = p.parse_args()\n    if torch.__version__.split(\"+\")[0] != \"2.5.1\":\n        raise RuntimeError(\"This record and API are pinned to torch 2.5.1\")\n    rank, world = int(os.environ[\"RANK\"]), int(os.environ[\"WORLD_SIZE\"])\n    if world != 2 or args.epochs not in (2, 4):\n        raise ValueError(\"This lesson fixes world_size=2 and epochs=2 or 4\")\n    torch.set_num_threads(1)\n    dist.init_process_group(\"gloo\", timeout=timedelta(seconds=40))\n    try:\n        # Identical seed, data, layers, optimizer and accumulation to reference_train.py.\n        seed, samples, hidden, batch_size, accum = 23, 1024, 32, 32, 2\n        data_rng = torch.Generator().manual_seed(seed)\n        x = torch.randn(samples, 128, generator=data_rng)\n        teacher = torch.randn(128, 10, generator=data_rng)\n        y = (x @ teacher).argmax(dim=1)\n        data = TensorDataset(x, y, torch.arange(samples))\n        sampler = DistributedSampler(data, num_replicas=world, rank=rank,\n                                     shuffle=True, seed=seed, drop_last=True)\n        loader_rng = torch.Generator().manual_seed(seed + 1000 + rank)\n        loader = DataLoader(data, batch_size=batch_size, sampler=sampler, drop_last=True,\n                            num_workers=0, generator=loader_rng)\n        torch.manual_seed(seed)\n        raw = nn.Sequential(nn.Linear(128, hidden), nn.ReLU(), nn.Dropout(0.1),\n                            nn.Linear(hidden, 10))\n        model = DDP(raw, broadcast_buffers=False)\n        optimizer = torch.optim.AdamW(model.parameters(), lr=1e-3, fused=False)\n        torch.manual_seed(seed + rank)\n        signature = {\"device\": \"cpu\", \"precision\": \"fp32\", \"batch_size\": batch_size,\n                     \"accum\": accum, \"samples\": samples, \"hidden\": hidden,\n                     \"seed\": seed, \"world_size\": world}\n        state = TrainState(model, optimizer, loader_rng, signature, args.weights_only)\n        if args.resume:\n            # Every rank participates. load calls state_dict then load_state_dict.\n            dcp.load({\"train\": state}, checkpoint_id=args.resume)\n            assert state.loaded\n        start = state.progress[\"next_epoch\"]\n        if start >= args.epochs:\n            raise ValueError(\"target_must_follow_resume_boundary\")\n        trace = []\n        for epoch in range(start, args.epochs):\n            sampler.set_epoch(epoch)\n            model.train()\n            optimizer.zero_grad(set_to_none=True)\n            first_ids, epoch_ids = None, []\n            for micro, (features, labels, ids) in enumerate(loader):\n                if first_ids is None:\n                    first_ids = ids.tolist()\n                epoch_ids.extend(ids.tolist())\n                update = (micro + 1) % accum == 0\n                with nullcontext() if update else model.no_sync():\n                    loss = nn.functional.cross_entropy(model(features), labels)\n                    (loss / accum).backward()\n                if update:\n                    optimizer.step()\n                    optimizer.zero_grad(set_to_none=True)\n                    state.progress[\"updates\"] += 1\n            state.progress[\"next_epoch\"] = epoch + 1\n            trace.append({\"epoch\": epoch, \"first_ids\": first_ids, \"all_ids\": epoch_ids,\n                          \"updates_after\": state.progress[\"updates\"]})\n\n        args.output.mkdir(parents=True, exist_ok=True)\n        # A new, immutable directory per run; this is synchronous DCP save.\n        dcp.save({\"train\": state}, checkpoint_id=args.output / \"checkpoint\")\n        all_rng = state.rng_states()\n        if rank == 0:\n            # A verification export, NEVER the path used to resume this program.\n            torch.save({\"model\": model.module.state_dict(), \"optimizer\": optimizer.state_dict(),\n                        \"scaler\": {}, \"next_epoch\": state.progress[\"next_epoch\"],\n                        \"signature\": signature, \"rng_by_rank\": all_rng}, args.output / \"comparison.pt\")\n        (args.output / f\"rank-{rank}.json\").write_text(json.dumps({\n            \"rank\": rank, \"pid\": os.getpid(), \"loaded\": state.loaded,\n            \"start_epoch\": start, \"progress\": state.progress, \"epochs\": trace,\n            \"optimizer_steps\": [int(v[\"step\"].item()) for v in optimizer.state.values()],\n        }, indent=2) + \"\\n\")\n        dist.barrier()\n    finally:\n        dist.destroy_process_group()\n\n\nif __name__ == \"__main__\":\n    main()\n", "run_lab.py": "\"\"\"Run old reference training, stop DCP processes, then restore in fresh ones.\n\nAll torch.load calls read local exports produced by this invocation, never an\nuntrusted download. DCP directories, not the comparison exports, resume training.\n\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\n\nimport torch\nimport torch.distributed.checkpoint as dcp\nfrom torch.utils.data import DistributedSampler\n\nHERE = Path(__file__).resolve().parent\n\n\ndef compare(a, b, path=\"state\"):\n    \"\"\"Independent recursive comparator: inspect every saved field, not a pass tag.\"\"\"\n    if isinstance(a, torch.Tensor):\n        if not isinstance(b, torch.Tensor) or a.dtype != b.dtype or a.shape != b.shape:\n            raise AssertionError(path + \": tensor_metadata\")\n        if not torch.equal(a, b):\n            raise AssertionError(path + \": tensor_values\")\n    elif isinstance(a, dict):\n        if not isinstance(b, dict) or a.keys() != b.keys():\n            raise AssertionError(path + \": keys\")\n        for key in a:\n            compare(a[key], b[key], path + \".\" + str(key))\n    elif isinstance(a, (tuple, list)):\n        if type(a) is not type(b) or len(a) != len(b):\n            raise AssertionError(path + \": sequence\")\n        for i, (x, y) in enumerate(zip(a, b)):\n            compare(x, y, path + \".\" + str(i))\n    elif a != b:\n        raise AssertionError(path + \": value\")\n\n\ndef launch(script, arguments, expect_success=True):\n    command = [sys.executable, \"-B\", \"-m\", \"torch.distributed.run\", \"--standalone\",\n               \"--nproc_per_node=2\", str(HERE / script)] + list(map(str, arguments))\n    environment = dict(os.environ, OMP_NUM_THREADS=\"1\", PYTHONDONTWRITEBYTECODE=\"1\")\n    result = subprocess.run(command, text=True, capture_output=True, timeout=90, env=environment)\n    if expect_success and result.returncode != 0:\n        raise RuntimeError(\"worker_failed\\n\" + result.stdout[-3000:] + result.stderr[-6000:])\n    if not expect_success and result.returncode == 0:\n        raise AssertionError(\"missing_metadata_was_accepted\")\n    return result\n\n\ndef load(path):\n    return torch.load(path, map_location=\"cpu\", weights_only=True)\n\n\ndef run(root):\n    baseline, stopped, resumed, weights = [root / n for n in [\"reference\", \"stopped\", \"resumed\", \"weights-only\"]]\n    launch(\"reference_train.py\", [\"--device=cpu\", \"--epochs=4\", \"--samples=1024\", \"--hidden=32\",\n                                  \"--batch-size=32\", \"--accum=2\", \"--save-dir\", baseline])\n    stopped_launch = launch(\"train_dcp.py\", [\"--epochs=2\", \"--output\", stopped])\n    # subprocess.run has waited for the torchrun parent AND both workers to exit.\n    assert stopped_launch.returncode == 0\n    launch(\"train_dcp.py\", [\"--epochs=4\", \"--resume\", stopped / \"checkpoint\", \"--output\", resumed])\n    reference, restored = load(baseline / \"checkpoint.pt\"), load(resumed / \"comparison.pt\")\n    compare(reference, restored)\n\n    traces = [json.loads((resumed / f\"rank-{r}.json\").read_text()) for r in range(2)]\n    stopped_traces = [json.loads((stopped / f\"rank-{r}.json\").read_text()) for r in range(2)]\n    expected_first = []\n    for rank, trace in enumerate(traces):\n        assert trace[\"loaded\"] and trace[\"start_epoch\"] == 2\n        assert trace[\"progress\"] == {\"next_epoch\": 4, \"updates\": 32}\n        assert trace[\"optimizer_steps\"] == [32] * 4\n        # Separate sampler construction outside train_dcp.py checks real consumed IDs.\n        for epoch_record in trace[\"epochs\"]:\n            sampler = DistributedSampler(range(1024), num_replicas=2, rank=rank,\n                                         shuffle=True, seed=23, drop_last=True)\n            sampler.set_epoch(epoch_record[\"epoch\"])\n            expected = list(iter(sampler))\n            assert epoch_record[\"all_ids\"] == expected\n            assert epoch_record[\"first_ids\"] == expected[:32]\n        expected_first.append(trace[\"epochs\"][0][\"first_ids\"])\n\n    launch(\"train_dcp.py\", [\"--epochs=4\", \"--resume\", stopped / \"checkpoint\",\n                            \"--output\", weights, \"--weights-only\"])\n    bad = load(weights / \"comparison.pt\")\n    # Input and randomness still match: this counterexample isolates lost Adam history.\n    compare(reference[\"rng_by_rank\"], bad[\"rng_by_rank\"])\n    assert reference[\"next_epoch\"] == bad[\"next_epoch\"] == 4\n    try:\n        compare(reference, bad)\n    except AssertionError as error:\n        negative_difference = str(error)\n    else:\n        raise AssertionError(\"reset_adam_was_not_detected\")\n    max_error = max(float((reference[\"model\"][k] - bad[\"model\"][k]).abs().max()) for k in reference[\"model\"])\n    assert max_error > 0\n\n    missing = root / \"missing-metadata\"\n    shutil.copytree(stopped / \"checkpoint\", missing)\n    (missing / \".metadata\").unlink()\n    failure = launch(\"train_dcp.py\", [\"--epochs=4\", \"--resume\", missing,\n                                      \"--output\", root / \"must-not-complete\"], expect_success=False)\n    assert \".metadata\" in failure.stderr and \"FileNotFoundError\" in failure.stderr\n    assert not (root / \"must-not-complete/comparison.pt\").exists()\n    metadata = dcp.FileSystemReader(stopped / \"checkpoint\").read_metadata()\n    files = [{\"name\": p.name, \"bytes\": p.stat().st_size,\n              \"sha256\": hashlib.sha256(p.read_bytes()).hexdigest()}\n             for p in sorted((stopped / \"checkpoint\").iterdir())]\n    return {\n        \"status\": \"passed\", \"torch\": torch.__version__, \"backend\": \"gloo\", \"device\": \"cpu\",\n        \"world_size\": 2, \"reference\": \"unaltered copy of existing labs/ddp/train_ddp.py\",\n        \"config\": reference[\"signature\"], \"continuous_epochs\": 4, \"split_epochs\": [2, 2],\n        \"restored_next_epoch\": restored[\"next_epoch\"], \"applied_updates\": 32,\n        \"exact_fields\": [\"model\", \"optimizer\", \"scaler\", \"next_epoch\", \"signature\", \"rng_by_rank\"],\n        \"all_reference_fields_exact\": True, \"old_launch_completed_before_resume\": True,\n        \"stopped_worker_pids\": [t[\"pid\"] for t in stopped_traces],\n        \"resumed_worker_pids\": [t[\"pid\"] for t in traces],\n        \"resume_first_batch_ids\": expected_first, \"independent_sampler_coverage\": [512, 512],\n        \"checkpoint_files\": files, \"metadata_key_count\": len(metadata.state_dict_metadata),\n        \"weights_only_control\": {\"restored_input_and_rng\": True, \"optimizer_restored\": False,\n                                 \"difference\": negative_difference, \"max_parameter_error\": max_error},\n        \"missing_metadata_control\": {\"exit_code\": failure.returncode, \"file_not_found\": True,\n                                     \"completed_state_exported\": False},\n        \"scope\": \"actual synchronous Stateful DCP, two local CPU/Gloo ranks, fixed epoch boundary; no FSDP/DTensor reshard/GPU/object store/power-loss claim\",\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--work-dir\", type=Path, help=\"Keep files in a new directory\")\n    args = parser.parse_args()\n    torch.set_num_threads(1)\n    if args.work_dir:\n        args.work_dir.mkdir(parents=True, exist_ok=False)\n        report = run(args.work_dir.resolve())\n    else:\n        with tempfile.TemporaryDirectory(prefix=\"torch-checkpoint-\") as directory:\n            report = run(Path(directory))\n    print(json.dumps(report, ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "reference_train.py": "\"\"\"Small, reproducible DDP lab. Run with torchrun; see README.md.\n\nEpoch-boundary recovery only, with a fixed world size and fixed batch settings.\nSynthetic classification data exercises the training plumbing, not LLM performance.\n\"\"\"\nimport argparse\nfrom contextlib import nullcontext\nfrom datetime import timedelta\nimport json\nimport os\nfrom pathlib import Path\nimport time\n\nimport torch\nfrom torch import nn\nimport torch.distributed as dist\nfrom torch.nn.parallel import DistributedDataParallel as DDP\nfrom torch.utils.data import DataLoader, TensorDataset, DistributedSampler\n\n\ndef arguments():\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument('--device', choices=['cpu', 'cuda'], default='cuda')\n    p.add_argument('--epochs', type=int, default=4, help='Total target epochs, including resumed epochs')\n    p.add_argument('--batch-size', type=int, default=64, help='Per-rank microbatch')\n    p.add_argument('--accum', type=int, default=2)\n    p.add_argument('--samples', type=int, default=8192)\n    p.add_argument('--hidden', type=int, default=256)\n    p.add_argument('--seed', type=int, default=23)\n    p.add_argument('--precision', choices=['fp32', 'bf16', 'fp16'], default='fp32')\n    p.add_argument('--save-dir', default='runs/demo')\n    p.add_argument('--resume', default='')\n    a = p.parse_args()\n    if min(a.epochs, a.batch_size, a.accum, a.samples, a.hidden) < 1:\n        p.error('epochs, batch-size, accum, samples and hidden must be positive')\n    if a.device == 'cpu' and a.precision != 'fp32':\n        p.error('This CPU verification path supports fp32 only')\n    if not all(k in os.environ for k in ('RANK', 'LOCAL_RANK', 'WORLD_SIZE')):\n        p.error('Use torchrun, even for a single process; see README.md')\n    return a\n\n\ndef report(rank, **record):\n    if rank == 0:\n        print(json.dumps(record, ensure_ascii=False), flush=True)\n\n\ndef save_checkpoint(path, model, optimizer, scaler, loader_rng, epoch, signature, device, rank, world):\n    save_began = time.perf_counter()\n    # Small teaching example: gather RNG state, not model tensors, to rank 0.\n    rng = {'cpu': torch.get_rng_state(), 'loader': loader_rng.get_state()}\n    if device.type == 'cuda':\n        rng['cuda'] = torch.cuda.get_rng_state(device)\n    all_rng = [None] * world if rank == 0 else None\n    dist.gather_object(rng, all_rng, dst=0)\n    if rank == 0:\n        path.parent.mkdir(parents=True, exist_ok=True)\n        temporary = path.with_name(path.name + '.tmp')\n        payload = {'model': model.module.state_dict(), 'optimizer': optimizer.state_dict(),\n                   'scaler': scaler.state_dict(), 'next_epoch': epoch + 1,\n                   'signature': signature, 'rng_by_rank': all_rng}\n        # Same-directory replace is atomic on a suitable POSIX filesystem.\n        # Not an object-storage commit protocol and not a power-loss guarantee.\n        with temporary.open('wb') as f:\n            torch.save(payload, f)\n            f.flush()\n            os.fsync(f.fileno())\n        os.replace(temporary, path)\n    dist.barrier()\n    report(rank, event='checkpoint', path=str(path), next_epoch=epoch + 1,\n           seconds=time.perf_counter() - save_began)\n\n\ndef train(a):\n    rank, local_rank, world = (int(os.environ[k]) for k in ('RANK', 'LOCAL_RANK', 'WORLD_SIZE'))\n    torch.set_num_threads(1)\n    if a.device == 'cuda':\n        if not torch.cuda.is_available() or local_rank >= torch.cuda.device_count():\n            raise RuntimeError('Each local process needs a distinct visible CUDA GPU')\n        torch.cuda.set_device(local_rank)\n        device = torch.device('cuda', local_rank)\n        if a.precision == 'bf16' and not torch.cuda.is_bf16_supported():\n            raise RuntimeError('BF16 is not supported by this device/runtime; use fp32 or fp16')\n    else:\n        device = torch.device('cpu')\n    dist.init_process_group('nccl' if a.device == 'cuda' else 'gloo', timeout=timedelta(seconds=120))\n    try:\n        # Identical fixed dataset across ranks. No external dataset download required.\n        data_rng = torch.Generator().manual_seed(a.seed)\n        x = torch.randn(a.samples, 128, generator=data_rng)\n        teacher = torch.randn(128, 10, generator=data_rng)\n        y = (x @ teacher).argmax(dim=1)\n        dataset = TensorDataset(x, y)\n        sampler = DistributedSampler(dataset, num_replicas=world, rank=rank,\n                                     shuffle=True, seed=a.seed, drop_last=True)\n        loader_rng = torch.Generator().manual_seed(a.seed + 1000 + rank)\n        loader = DataLoader(dataset, batch_size=a.batch_size, sampler=sampler,\n                            drop_last=True, num_workers=0, pin_memory=a.device == 'cuda',\n                            generator=loader_rng)\n        if len(loader) == 0 or len(loader) % a.accum:\n            raise ValueError('Per-rank batch count must be positive and divisible by --accum; '\n                             'adjust --samples/--batch-size/--accum')\n        torch.manual_seed(a.seed)\n        raw_model = nn.Sequential(nn.Linear(128, a.hidden), nn.ReLU(), nn.Dropout(0.1),\n                                  nn.Linear(a.hidden, 10)).to(device)\n        model = DDP(raw_model, device_ids=[local_rank] if a.device == 'cuda' else None,\n                    broadcast_buffers=False)\n        # Fix the non-fused path: its post hook observes a completed step call.\n        optimizer = torch.optim.AdamW(model.parameters(), lr=1e-3, fused=False)\n        applied_calls = 0\n\n        def count_step(_optimizer, _args, _kwargs):\n            nonlocal applied_calls\n            applied_calls += 1\n\n        optimizer.register_step_post_hook(count_step)\n        scaler = torch.amp.GradScaler('cuda', enabled=a.precision == 'fp16')\n        torch.manual_seed(a.seed + rank)  # Independent dropout streams, restored on resume.\n        signature = {k: getattr(a, k) for k in ('device', 'precision', 'batch_size', 'accum',\n                                                'samples', 'hidden', 'seed')}\n        signature['world_size'] = world\n        start = 0\n        if a.resume:\n            # Only load a trusted checkpoint from this lab. Every rank must read the same file.\n            state = torch.load(a.resume, map_location='cpu', weights_only=True)\n            if state['signature'] != signature:\n                raise ValueError('Resume requires the same world size, device, precision and training settings')\n            model.module.load_state_dict(state['model'])\n            optimizer.load_state_dict(state['optimizer'])\n            # Older lab checkpoints may store fused=None in the parameter groups.\n            for group in optimizer.param_groups:\n                group['fused'] = False\n            scaler.load_state_dict(state['scaler'])\n            start = state['next_epoch']\n            torch.set_rng_state(state['rng_by_rank'][rank]['cpu'])\n            loader_rng.set_state(state['rng_by_rank'][rank]['loader'])\n            if a.device == 'cuda':\n                torch.cuda.set_rng_state(state['rng_by_rank'][rank]['cuda'], device)\n        if start >= a.epochs:\n            raise ValueError('--epochs is the total target and must be greater than checkpoint next_epoch')\n        effective_batch = a.batch_size * a.accum * world\n        report(rank, event='start', world_size=world, backend=dist.get_backend(),\n               effective_batch=effective_batch, start_epoch=start, precision=a.precision,\n               torch_version=str(torch.__version__))\n        for epoch in range(start, a.epochs):\n            sampler.set_epoch(epoch)\n            model.train()\n            optimizer.zero_grad(set_to_none=True)\n            loss_sum = torch.zeros((), device=device)\n            seen = 0\n            attempted_windows = 0\n            applied_at_start = applied_calls\n            dist.barrier()\n            if a.device == 'cuda':\n                torch.cuda.synchronize(device)\n            began = time.perf_counter()\n            for step, (features, labels) in enumerate(loader):\n                features = features.to(device, non_blocking=True)\n                labels = labels.to(device, non_blocking=True)\n                update = (step + 1) % a.accum == 0\n                # no_sync must cover BOTH forward and backward.\n                with nullcontext() if update else model.no_sync():\n                    with torch.autocast(device_type=a.device,\n                                        dtype=torch.bfloat16 if a.precision == 'bf16' else torch.float16,\n                                        enabled=a.precision != 'fp32'):\n                        loss = nn.functional.cross_entropy(model(features), labels)\n                    scaler.scale(loss / a.accum).backward()\n                loss_sum += loss.detach() * labels.numel()\n                seen += labels.numel()\n                if update:\n                    attempted_windows += 1\n                    scaler.step(optimizer)\n                    scaler.update()\n                    optimizer.zero_grad(set_to_none=True)\n            if a.device == 'cuda':\n                torch.cuda.synchronize(device)\n            duration = torch.tensor(time.perf_counter() - began, device=device, dtype=torch.float64)\n            totals = torch.stack((loss_sum.double(), torch.tensor(float(seen), device=device, dtype=torch.float64)))\n            dist.all_reduce(duration, op=dist.ReduceOp.MAX)\n            dist.all_reduce(totals, op=dist.ReduceOp.SUM)\n            applied_this_epoch = applied_calls - applied_at_start\n            counts = torch.tensor([attempted_windows, applied_this_epoch], device=device)\n            minimum, maximum = counts.clone(), counts.clone()\n            dist.all_reduce(minimum, op=dist.ReduceOp.MIN)\n            dist.all_reduce(maximum, op=dist.ReduceOp.MAX)\n            if not torch.equal(minimum, maximum):\n                raise RuntimeError('Ranks disagree on attempted windows or applied optimizer calls')\n            report(rank, event='epoch', epoch=epoch + 1, loss=(totals[0] / totals[1]).item(),\n                   samples=int(totals[1].item()), seconds=duration.item(),\n                   samples_per_second=(totals[1] / duration).item(),\n                   attempted_update_windows=attempted_windows,\n                   applied_optimizer_steps=applied_this_epoch,\n                   optimizer_steps=applied_this_epoch)\n            save_checkpoint(Path(a.save_dir) / 'checkpoint.pt', model, optimizer, scaler,\n                            loader_rng, epoch, signature, device, rank, world)\n    finally:\n        dist.destroy_process_group()\n\n\nif __name__ == '__main__':\n    train(arguments())\n", "README.md": "# 从已有 DDP 训练走到原生 DCP 恢复\n\nPython 3.12、PyTorch 2.5.1；两条本机 CPU/Gloo 进程，固定 epoch 边界。\n\n```sh\npython3.12 -m venv .venv\n.venv/bin/pip install -r requirements.txt\n.venv/bin/python -B run_lab.py > local-record.json\n# 可选：保留检查点和逐 rank 输入记录。runs 必须尚不存在。\n.venv/bin/python -B run_lab.py --work-dir runs > retained-record.json\n```\n\n`reference_train.py` 是原 DDP 章节 `labs/ddp/train_ddp.py` 的逐字副本；它保留\nrank 0 的 torch.save 路径，作为独立保存实现的连续四轮基线。不要修改它来迁就\nDCP 输出。新程序用相同数据、128→32→10 的含 Dropout 模型、AdamW、每 rank\n32 样本微批、累积两次、1024 样本和 seed=23。每轮8次更新，共32次。\n\n`run_lab.py` 顺序等待每一批 torchrun 及其子进程结束，再启动下一批：\n\n1. 原程序连续训练四轮。\n2. 新程序训练两轮，由所有 rank 调用同步 DCP save；旧进程退出。\n3. 新进程创建模型、优化器及目标状态树，DCP load 后继续到第四轮。\n4. 用独立递归比较器逐项检查原基线与恢复结果的模型、完整 Adam 状态、RNG、\n   scaler 空状态、next_epoch 和配置。单独构造采样器核对恢复后的实际输入 ID。\n5. 负例保留相同权重、恢复边界和 RNG，却不恢复 Adam 历史；最终参数必须不同。\n6. 复制两轮检查点，删除 `.metadata`，新加载必须报错且不产出完成状态。\n\n`comparison.pt` 只是结束后的可信本地验证导出，恢复程序从不读取它；恢复始终\n读取 DCP 目录。`TrainState.state_dict` 通过 get_state_dict 取得模型/优化器的\n统一名称；加载调用 set_state_dict。各 rank RNG 先汇集成相同列表，再保存；\n恢复后选择自己的 RNG。新建优化器的目标状态由 get_state_dict 初始化，再由\n加载值覆盖。两 rank 都调用 save/load，不把 DCP 包在 if rank == 0 内。\n\nDCP 负责这一目录中状态项的规划、写入和加载；`.metadata` 描述实际存储位置。\n它不替应用决定应恢复哪一次训练。原 CURRENT 教学协议负责选择已发布恢复点，\n若生产使用对象存储、并发 attempt 或 latest 指针，仍要有相应提交规则。本包\n每次使用新目录，第一版只验证同步保存和正常进程退出后的恢复。\n\n这是实际 PyTorch API、CPU Dropout/Adam 和两 rank 通信；不是 FSDP 参数分片、\nDTensor 弹性重分片、GPU/NCCL、异步保存、跨机共享存储或掉电持久性验收。\n只加载本次自己生成的可信文件。validation.json 记录环境、源码摘要和本次结果。\n\n一手实现（固定 v2.5.1）：\n\n- https://github.com/pytorch/pytorch/blob/v2.5.1/torch/distributed/checkpoint/state_dict_saver.py\n- https://github.com/pytorch/pytorch/blob/v2.5.1/torch/distributed/checkpoint/state_dict_loader.py\n- https://github.com/pytorch/pytorch/blob/v2.5.1/torch/distributed/checkpoint/state_dict.py\n- https://github.com/pytorch/pytorch/blob/v2.5.1/torch/distributed/checkpoint/filesystem.py\n", "requirements.txt": "torch==2.5.1\n"};
