// progressive-sre-reading.js
/* User events -> measured signals -> discriminating evidence.
   Keep the published section destinations and original executable evidence. */
(()=>{
 if(typeof articles==='undefined')return;
 const p=(...items)=>items.map(text=>'<p>'+text+'</p>').join('');
 const table=(heads,rows)=>'<div class="table-wrap"><table><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const fold=(title,body)=>'<details class="progressive-detail"><summary>'+title+'</summary>'+body+'</details>';
 const matches=(body,re)=>[...body.matchAll(re)].map(m=>m[0]);
 const pres=body=>matches(body,/<pre\b[^>]*>[\s\S]*?<\/pre>/g);
 const codes=body=>matches(body,/<div class="code-block">[\s\S]*?<\/pre><\/div>/g);
 const figures=body=>matches(body,/<figure\b[\s\S]*?<\/figure>/g);
 const hrefs=body=>matches(body,/\bhref=["'][^"']+["']/g);
 const ids=body=>[...body.matchAll(/\bid=["']([^"']+)["']/g)].map(m=>m[1]);
 const links=body=>matches(body.replace(/<figure\b[\s\S]*?<\/figure>/g,'').replace(/<div class="code-block">[\s\S]*?<\/pre><\/div>/g,''),/<a\b[^>]*href=["'][^"']+["'][^>]*>[\s\S]*?<\/a>/g);
 const linkRow=items=>items.length?'<p class="practice-links">'+items.join(' · ')+'</p>':'';
 const figure=(name,width,height,caption)=>'<figure class="training-figure"><a href="diagrams/'+name+'.svg" target="_blank" rel="noopener" aria-label="放大：'+caption+'"><img src="diagrams/'+name+'.svg" width="'+width+'" height="'+height+'" alt="'+caption+'" loading="lazy"><span class="figure-zoom-hint">点击图示放大 ↗</span></a><figcaption>'+caption+'<a href="diagrams/'+name+'.svg" download>下载 SVG ↗</a></figcaption></figure>';
 function same(label,before,after){if(JSON.stringify(before)!==JSON.stringify(after))throw Error('V71 SRE changed '+label);}
 function includesAll(label,before,after){
  const remaining=after.slice();
  before.forEach(item=>{const at=remaining.indexOf(item);if(at<0)throw Error('V71 SRE lost '+label+': '+item);remaining.splice(at,1);});
 }
 function finish(a,old,bodies,minutes){
  same(a.id+' section count',old.length,bodies.length);
  bodies.forEach((body,index)=>{
   same(a.id+' section '+(index+1)+' code bytes/order',pres(old[index]),pres(body));
   includesAll(a.id+' section '+(index+1)+' figures',figures(old[index]),figures(body));
   includesAll(a.id+' section '+(index+1)+' URL multiplicity',hrefs(old[index]),hrefs(body));
   includesAll(a.id+' section '+(index+1)+' explicit IDs',ids(old[index]),ids(body));
   if(!body||body===old[index])throw Error('V71 SRE section not revised: '+a.id+' '+(index+1));
  });
  same(a.id+' global code bytes/order',pres(old.join('')),pres(bodies.join('')));
  bodies.forEach((body,index)=>a.sections[index][1]=body);
  a.updated='2026.11.09';a.minutes=minutes;
 }

 {
  const a=articles.find(x=>x.id==='slo');
  if(!a)throw Error('V71 missing SLO chapter');
  same('SLO section identities',a.sections.map(s=>s[0]),['从用户等待查询开始定义好事件','按请求计数，不能按实例平均','错误预算是一段窗口内可消耗的坏事件','把燃烧速度与来得及采取的动作联系起来','低流量与无流量需要不同的解释','把预算反推到一次发布决定','评分练习：两组流量和一次快速消耗','配套实战：真实Prometheus规则求值']);
  const old=a.sections.map(s=>s[1]),c=old.map(codes),f=old.map(figures),l=old.map(links);
  same('SLO code inventory',c.map(x=>x.length),[0,0,1,0,0,1,0,5]);
  const bodies=[
   p('用户打开日报，服务接收查询，核对归属与版本，读取内容，再把结果交还用户。可靠性首先问这次工作有没有按约定完成。入口返回HTTP 200，但日报属于别人、版本过旧或用户已经等到超时，都可能没有完成这项工作。',
   '一次纳入统计的用户操作称为事件。本章选合法的日报查询，事先排除健康探针和范围之外的非法输入；好事件要求归属、版本都正确，且从约定入口到结果交付不超过500毫秒。其余已判定事件为坏事件。这个分类把业务结果与时间要求连在同一次查询上。')+
   table(['对象','保存或比较什么','本章怎样使用'],[
    ['服务水平指标 SLI','按事件定义算出的实际好率','同窗好查询数 ÷ 同窗纳入统计的全部查询数'],
    ['服务水平目标 SLO','指标应达到的阈值及统计窗口','给一份已结算窗口设定好率至少99%'],
    ['错误预算','该目标允许的坏事件量','同窗总数 × (1−目标好率)']
   ])+p('先约定窗口归属，再结算结果。例如查询在12:00:59.900到达，以到达时刻归入12:00这一分钟；500毫秒期限到12:01:00.400才满。刚过12:01时，它仍待结算。留给结果判定与采集到达的时间，不会延长用户的500毫秒要求；到约定判定点仍未及时成功，就应计坏，不能因为缺少完成日志把它删掉。',
   '同一操作触发客户端重试时，也要固定统计层级：按用户操作统计，用稳定操作身份关联所有尝试和总等待；按API调用尝试统计，两次尝试都计数。分子、分母必须属于同一层。可用性和延迟若另设独立指标，也各有自己的分母，不能直接相乘两份好率获得本章的复合好率。后面的计数题都假定分类与结算已经完成。'),

   p('现在读取同一观察窗的事件账本：甲处理900次，899好、1坏；乙处理100次，90好、10坏。用户一共发起1000次查询，好989次、坏11次。因此总体SLI为989/1000=98.9%。实例是处理请求的副本，拆分实例不会凭空改变用户事件。')+f[1][0]+
   p('甲的好率约99.89%，乙为90%；简单平均约94.94%，相当于让两组各占一半权重。甲的900次查询因此被压成与乙的100次同样重要。按请求量加权才会还原989/1000；实际查询更直接的做法是先加好事件、再加总事件，最后除一次。',
   '能合并的前提是事件定义、窗口归属和分组范围相同。跨区域、实例或部署版本时先核对这三项，再聚合。累计计数器在进程重启后会归零，窗口增量应逐序列处理重置；不能直接拿重启前后的原值相减。若新版改变了好事件定义，应先对同一批原始请求重算。',
   '总体目标反映全部请求，但不保证每个租户都体验相同。可以另看租户、区域或版本的同口径切片，并为关键租户建立独立目标。切片用于发现影响集中在哪里，不能把受影响切片从总体分母中删掉。'),

   p('目标为99%时，允许坏率是1%。对同窗1000次查询，错误预算为1000×1%=10次；实际坏11次，剩余10−11=−1次。负值表示这个窗口已未达到目标。预算用同一个请求总体计算，不能拿一天的坏事件去减一个月的允许量。',
   '燃烧率把实际坏率除以目标允许坏率，表示消耗速度相对目标有多快。本例坏率11/1000=1.1%，燃烧率为1.1%/1%=1.1倍。它是无量纲的比值；当窗口事件已经结算，消耗预算的比例也可直接算成11/10=110%。')+c[2][0]+
   p('程序使用Python标准库Fraction保存精确分数，输出SLI=989/1000、允许坏事件10、剩余−1、燃烧倍数11/10。它计算题设账本，没有采集服务。可先把目标改成99.5%：同一批请求只允许5坏，实际11坏，燃烧率就变为2.2倍；用户经历没有改变，承诺变严了。',
   '窗口决定哪些事件仍参与比较。30天滚动窗口随着旧事件移出、新事件加入而变化；自然月窗口在月界线换成新一批事件。请求型目标按事件数加权，高峰一分钟和深夜一分钟可能承载不同数量的请求，所以99%好率不能直接换成固定的不可用分钟数。按时间片定义的可用性是另一种口径。')+'<div id="slo-demo"></div>',

   p('告警要在仍来得及减少后续损失时发出。这里另设30天、99.9%的目标，允许坏率0.1%，按30×24=720小时估算。最近1小时坏率若为1.44%，燃烧率就是1.44%/0.1%=14.4倍。这个小时的局部坏率可以从事件量求得，整窗预算占比还要知道整窗有多少请求。',
   '先固定均匀流量：每小时1万次，整窗720万次，允许坏7200次。该小时坏144次，消耗144/7200=2%的整窗预算，也等于14.4×1/720。若从完整预算开始，同样流量和坏率一直持续，约720/14.4=50小时用完。这些条件变了，外推时间也会变。')+
   table(['同一坏小时的两种整窗条件','整窗总数 / 允许坏','该小时实际坏','整窗预算消耗'],[
    ['均匀流量估算','720万 / 7200','144','2%'],
    ['已结束的不均匀流量窗口','100万 / 1000','144','14.4%']
   ])+p('第二行中该小时仍有1万次请求，所以局部燃烧率仍为14.4倍，但它占月流量的比例更高。复盘实际损耗时，用真实坏事件和整窗事件量核算；不能把每小时机械视作月流量的1/720。',
   '多窗口告警用长窗口判断损耗已经持续到一定规模，再用包含其中的短窗口确认当前还在恶化。例如最近1小时和5分钟的坏率都大于1.44%，才满足本章的快速分支。两窗读取同一事件流，有重叠，不能把两份坏数再相加。',
   '长窗仍高、短窗已恢复时，这一快速分支可以停止；历史坏事件仍留在30天窗口。更慢的损耗需要另一组更长窗口与相应响应级别。本章实战只实现这一组快速分支，未宣称已覆盖所有慢烧、缺数或通知故障。阈值选择应与团队响应所需时间、可执行的止损动作相配。'),

   p('如果5分钟只有3次查询、1次坏，坏率是1/3；99.9%目标下燃烧率约333.3倍。算式正确，但只描述这3次请求。一次关键任务失败值得处理，仍不能由此断言全部租户已经大面积故障。显示坏数与总数，才能让读者看见比值背后的样本量。',
   '低流量时可以延长窗口，或合并用户意义和故障模式相近的请求组。对极少触发的重要路径，合成探测由受控客户端定期发起已知操作，补充基本可达性的证据。它有独立的分母和覆盖范围；探针成功不代表真实用户的权限、资料大小和版本都正确，不能大量掺入用户分母稀释失败。')+
   table(['观察到什么','指标怎样解释','还要核对什么'],[
    ['有请求、错误计数为0','在已覆盖的这批请求中无坏事件','错误分类是否完整，成功条件是否检查'],
    ['计数器存在、窗口总增量为0','没有用户样本，0/0不产生成功比例','确实无需求，还是请求进不了入口'],
    ['整个请求序列缺失','没有这份遥测证据','采集心跳、目标存活和独立客户端信号']
   ])+p('入口没有请求也可能是上游路由损坏，缺数据也可能是采集链中断。把入口计数、客户端结果和采集状态放在同一时间线比较，才能区分这些解释。无流量保护可以避免无意义的比值告警，却同时意味着要另有路径发现“请求根本到不了”。'),

   p('日报新版开始小流量发布，总体预算仍剩一半，但某个大租户的新版切片正在快速消耗。先比较同类查询、相同窗口和版本，确认旧版与新版承接的资料和流量可比；再沿错误结果或慢路径定位到新版的具体变化。预算说明损害规模，版本切片帮助决定暂停扩大还是回切流量。',
   '回切前要确认旧版仍能读当前数据，并保存发布时刻、流量路由和关键请求证据。可用性预算即使充足，也不能为跨租户读取或错误数据签发许可：这些事件需要独立的正确性与权限处置条件。',
   '处置后先重做受影响查询，确认结果与等待恢复，再检查未完成请求和下游压力。5分钟告警消失表示近期快速损耗停止；30天目标是否重新达标，要重新读取该窗口账本。修复不会撤销已发生的11个坏事件。',
   '系统实验包中的合成指标程序提供另一份独立账本，可核对全局计数、预算与无流量结果。解压后执行下列命令；先读取报告的事件量和目标，再代公式。它检验算术，遥测覆盖仍需在真实服务上对账。')+c[5][0],

   p('独立练习固定同一窗口：甲990次查询、4坏，乙10次、1坏，目标99.8%。先合并得到1000次、5坏；坏率5/1000=0.5%。允许坏数1000×0.2%=2，剩余预算2−5=−3，燃烧率0.5%/0.2%=2.5倍。乙的10%以10次为分母，既应被看到，也不能与甲坏率等权平均当成总体。',
   '再改变一个条件：下一段5分钟入口计数器没有增长，而独立客户端持续超时。这里不能报告100%成功。应保留用户指标无样本状态，对照客户端发出量、上游到达量与采集心跳，判断请求在哪里消失。',
   '核对解答时分别检查全量分母、允许坏数、燃烧率和低样本解释，各占一分。发布决定还应写明：什么结果会暂停扩大，什么证据支持恢复；不能只用“预算还有”代替业务条件。')+linkRow(l[6])+
   p('一次报表发布收到过 HTTP 503，接收方最后只保存了一份正确的报表。<a href="/article/observability/#slo-event-to-trace">到下一章按实际结果计数，再沿追踪找出哪次调用失败 →</a>'),

   '<h3 id="subsection-8-fgmzv3">在真实规则引擎中检验聚合与告警</h3>'+p('Prometheus按时间保存指标样本。计数器是随事件累加、进程重启时可能重置的数值；标签区分同名指标的实例、结果类别等序列。实验先把业务事件分类成good/bad，再输入http_requests_total；规则引擎不会替业务判断版本正确或用户是否拿到了日报。记录规则将定期计算的值存为新指标，告警规则再比较这些值并维护每组标签的告警状态。',
   '此处固定30天、99.9%的目标，读取1小时和5分钟坏率，两个都严格大于14.4×0.001=0.0144且5分钟有流量时，先进入待确认pending。规则每分钟求值一次；条件持续满足1分钟后变为触发firing。1分钟是告警状态的等待条件，不是额外的统计窗，也不是收集够1分钟就能忽略1小时输入。')+
   table(['代码对象','从输入到结果的职责','成立条件'],[
    ['rate(counter[5m])与rate(counter[1h])','估计各序列窗口内每秒增量，处理计数器重置','先逐序列rate，再聚合，保留重启边界'],
    ['sum by(job)','合并同服务的实例与结果序列','分子分母按相同job和事件范围分组'],
    ['bad or on(job) (0 * total)','坏序列不存在而总流量存在时，为相同job补0','补的是坏数；总序列缺失时不会凭空生成健康数据'],
    ['job:slo_bad_ratio5m与job:slo_bad_ratio1h','记录本轮求值得到的两个窗口坏率，供告警使用','各自保存同一事件流在相应窗口的结果'],
    ['and on(job) 与 for: 1m','连接同job的条件；持续活跃后从pending转firing','任一必要条件不满足，该快速分支就不成立']
   ])+p('rate使用采样点估计并向窗口边界外推；increase等于对应rate乘窗口秒数，所以一般可能出现非整数。这里的固定线性序列与采样间隔使测试预期可精确核对，不能把任何真实rate结果都当成逐请求账本的精确条数。官方函数与告警规则文档分别说明这些语义。')+
   c[7][0]+
   table(['七组固定输入','独立预期及实际断言'],[
    ['按请求量聚合','A每分钟20好、0坏，B为162好、18坏；5分钟共1000次、90坏，成功率0.91'],
    ['持续热故障','每分钟98好、2坏，坏率2%大于1.44%；60m检查时告警已触发'],
    ['短窗恢复','坏计数停止增加；65m时1h仍高、5m坏率0，快速告警不再触发'],
    ['兼容经典直方图合并','同边界桶先合并，p99插值估计0.99秒；实例估计等权平均0.545秒不同'],
    ['有流量但无bad序列','同job的total存在，补零后坏率0'],
    ['零流量','总速率0，0/0为NaN，不展示为100%成功；流量条件不成立'],
    ['所有请求序列缺失','坏率结果为空；absent_over_time单独识别缺数']
   ])+p('七组是独立测试输入。第一组A共100次全好，B共900次、810好；它们与前文甲900次、899好的账本不同，不能沿用989/1000。直方图对照的0.99秒也是桶插值结果，不是逐条原始时长的最近秩分位数。')+c[7][1]+
   fold('查看实际求值的 recording / alerting rules',c[7][2])+
   fold('查看七组输入序列与预期断言',c[7][3])+
   fold('查看调用真实 promtool 的验证驱动',c[7][4])+
   p('历史记录使用Prometheus 3.5.0的promtool，规则解析与七组求值均退出0。fuzzy_compare只容忍最后位浮点差异，标签与分支断言仍保留。这里没有启动抓取服务、检验真实遥测覆盖、交付Alertmanager通知或执行值班响应。')+
   '<p class="source-at">规则语义：<a href="https://prometheus.io/docs/prometheus/latest/querying/functions/" target="_blank" rel="noopener">Prometheus · rate、increase与分位函数 ↗</a> · <a href="https://prometheus.io/docs/prometheus/latest/configuration/alerting_rules/" target="_blank" rel="noopener">Prometheus · 告警状态与for ↗</a></p>'+linkRow(l[7])
  ];
  finish(a,old,bodies,22);
  a.sections[1][1]+=
   '<h3 id="cpu-quota-sli-events">同样 100 次请求，有几次按时完成</h3>'+
   p('取 <a href="/article/elasticity/#native-cpu-quota-http">C8.1 的两档 CPU 配额实测</a>。两档各发 100 次。收到 HTTP 200、回执 ID 与请求相符，而且从发出请求到收完整个响应不超过 500 毫秒，才记为好事件。入口返回 503 的请求也在这 100 次里。')+
   table(['服务端配额','及时的 200','迟到的 200','入口拒绝 503','好事件 / 全部请求'],[
    ['1 核','100','0','0','100/100（100%）'],
    ['0.25 核','4','31','65','4/100（4%）']
   ])+
   p('打开<a href="/labs/cpu-quota-http/validation.json">逐请求记录</a>，在 <code>report.runs.tight.arrivals</code> 按 ID 找第 4、5 次请求。两次都是 200。用 <code>received_ns - sent_ns</code> 算客户端耗时，分别约 411.976 和 627.136 毫秒。按本节门槛，前者达标，后者超过门槛。计算时以纳秒比较，500 毫秒等于 500,000,000 纳秒。')+
   p('受限档若只数 200，分母会变成 35，得到 4/35。它回答的是成功响应中有几次及时。用户侧的达标比例把 65 次拒绝也计入，结果是 4/100。500 毫秒是本节用来重算的门槛，记录覆盖这两批实测请求。长期目标与告警另按各自的统计窗口结算。');
 }

 {
  const a=articles.find(x=>x.id==='observability');
  if(!a)throw Error('V71 missing observability chapter');
  same('observability section identities',a.sections.map(s=>s[0]),['从一个能复述的用户现象开始','RED 看用户请求，USE 查资源上的排队','为什么局部 p99 不能拼成全局 p99','直方图让“超过目标的有几次”比 p99 更直接','让指标可定位，同时控制标签组合','还原一次慢请求的因果路径','观测链也有失败模式，用已知输入校核它','课堂验收：查出故障，也查出图表的问题','配套实战：两段HTTP与父子trace关联']);
  const old=a.sections.map(s=>s[1]),c=old.map(codes),l=old.map(links);
  same('observability code inventory',c.map(x=>x.length),[0,0,0,0,0,0,0,0,2]);
  const bodies=[
   p('用户查询订单列表：客户端发出请求，入口接收，应用读取库存和物流信息，组装响应，客户端取得结果。请求是这一次调用；时长是选定结束点减开始点。入口处理时长从入口接收算到响应交出，用户等待还可能包含到入口之前、响应到客户端之后的时间，测量边界应随数值一起写明。',
   '十点到十点零五分，部分租户查询变慢。先固定用户操作、窗口、部署版本和区域，再问正常结果应是什么。一次请求即使在后台重试两次，仍是一次用户操作、三个内部尝试。分别记录入口开始、完成、失败与取消，才能看见没有正常返回的用户。')+
   table(['信号','它保存什么','沿这次查询回答什么'],[
    ['指标 metric','按名称和有限标签聚合的数值，随时间采样','多少请求变慢，集中在哪个版本或区域'],
    ['日志 log','某个时点发生的离散事件及上下文字段','该请求为何重试、返回哪一版资料、哪次租借失败'],
    ['追踪 trace','相关操作组成的一次执行路径','入口查询触发了哪些内部调用'],
    ['跨度 span','追踪中一次有起止时刻的操作及其身份、父关系','库存调用持续多久，是否挡住响应返回']
   ])+p('可观测性是用系统留下的这些信号解释内部行为的能力。指标先缩小影响范围，再沿同一请求身份找到日志与追踪；trace-id关联整条路径，span-id区分其中一次操作。光有一条错误日志无法计算影响面，光有延迟曲线又无法说明在等哪个步骤。用户事件与好坏分类仍按同一口径对账。')+linkRow(l[0])+
   '<h3 id="slo-event-to-trace">一次报表发布里，哪一步返回了 503</h3>'+
   p('沿用上一章的分类方法，把事件换成一次报表发布。本练习要求程序在 500 毫秒内核对完接收方返回的保存回执。接收方必须只保存一份报表，报表总数为 37。实际记录中的 <code>R27-retry</code> 从开始执行到完成核对用了 6.525 毫秒。账本标为已核对成功，接收方也只存了一份总数为 37 的报表，所以计一次好事件。',
   '用账本上的追踪编号查到这次任务。记录整项工作的跨度叫根跨度。它下面有两次 HTTP 调用，每次又有一条接收端跨度，其父编号就是相应调用的跨度编号。')+
   table(['调用','接收端做了什么','调用方收到什么'],[
    ['第一次','保存报表，总数 37','HTTP 503'],
    ['第二次','找到原有报表，复用回执','HTTP 200']
   ])+p('这次 503 出现在写入之后。第二次调用取得回执，程序才核对任务完成。两次内部调用仍只对应一次任务。下一章换用两次真实的 SQLite 查询。后来的查询借不到连接时，用同样的方法查清<a href="/article/incident/#incident-connection-lease">占着连接的请求正在等什么 →</a>')+
   fold('核对实际追踪编号和起止时刻',p('账本中 <code>R27-retry</code> 的追踪编号是 <code>a881e26b5aad26904c03d43be64547ad</code>，根跨度是 <code>8048db061ee16091</code>。起止时刻为 <code>1794205272194587000</code> 与 <code>1794205272201112000</code> 纳秒，相减得 6525000 纳秒。两次调用跨度是 <code>3df97674fe31c7d2</code> 与 <code>8c5d1c5f37af2c1e</code>；在接收端记录的 <code>parentSpanId</code> 分别能找到它们。')+
   '<p class="practice-links"><a href="/labs/otel-tail-ledger/ledger.sqlite">任务、调用与报表账本 ↗</a> · <a href="/labs/otel-tail-ledger/full-traces.jsonl">原始跨度 ↗</a> · <a href="/labs/otel-tail-ledger/validation.json">运行与验证记录 ↗</a></p>'),

   p('RED围绕对外请求观察Rate请求速率、Errors失败和Duration持续时间。先数固定窗口内的请求，再按业务结果分类，最后保留时长分布。本章统计例固定5分钟：A实例990次、1失败，B实例10次、5失败。总体1000次，速率1000/300≈3.33次/秒，失败率6/1000=0.6%。',
   'A失败率约0.101%，B为50%，等权平均约25.05%。这个值错误地让B的10次占一半权重。总体0.6%用于描述全部请求，B的50%用于识别影响集中在哪个实例、区域或版本，两种视图应同时保留。HTTP 200若内容不正确也可以是业务失败，不能只按协议状态上色。',
   '请求变慢后，沿它实际依赖的资源查USE：Utilization利用率表示资源被使用的程度；Saturation饱和程度看未获资源的工作是否在等；Errors看资源报告的失败。连接池是可复用数据库连接的有限集合，应用借到连接后才能执行SQL数据库查询，归还后另一项工作才能使用。',
   '若8个连接全被借出、另有18个任务等待，连接资源已出现排队；主机CPU只占三成也能同时成立，因为等连接的任务未必在执行计算。接着查看谁持有连接、持有多久、其中SQL真正执行多久。若持有者在等另一个服务，加连接可能只把并发压力推给数据库。',
   '资源错误与用户失败也不是同一计数：磁盘重试成功，资源记录了错误而用户可能成功；请求被权限规则拒绝，资源仍可能健康。RED定位用户变化，USE检验承接它的资源，两组观察通过真实请求路径相连。')+linkRow(l[1]),

   p('持续时间分布保留不同请求分别花了多久。百分位从这份分布中选位置：采用最近秩nearest-rank约定，n个时长升序排列后，p99取第ceil(0.99×n)项。它回答99%的观察值不超过哪里；它不记录其余每个值。',
   '用独立的100条时长演示：A的99次均为10毫秒，B的一次为1000毫秒。A的p99=10，B的p99=1000；合并排序后第99项仍是10，所以全局p99=10毫秒。两实例p99平均是505毫秒，按99:1加权是19.9毫秒，均不能从已丢失的分布中恢复全局p99。')+
   figure('v71-sre-duration-distribution',1120,680,'同窗100条时长：99条10ms、1条1000ms。合并原始样本后按最近秩取第99项；局部分位数不能用平均合并。')+
   p('那一次1000毫秒仍真实存在，p99=10并未证明所有请求都快。小样本或稀少失败还需看最大值、超过业务阈值的数量和对应请求。图中累计桶把同一100条样本按上界计数；它们只保留区间信息。若没有原始值，桶内的精确位置通常无法还原。',
   '跨实例聚合需要原始样本，或能够合并的分布表示。Prometheus Summary客户端预先算出的分位数不能据此恢复总体；经典直方图保存兼容边界的桶计数，可在相同窗口先合并桶，再估计分位数。最近秩精确值与桶插值估计属于不同算法，读查询结果前应确认哪一种。')+linkRow(l[2]),

   p('经典直方图把时长按一组上界累计计数。“≤300ms”包括所有不超过300毫秒的样本，也包括“≤100ms”中的样本，因此累计桶不能直接相加。下面固定另一份1000个成功请求的窗口，学习桶内估计；它与上一节的100条精确样本、RED的1000条所有结果各有独立总体。')+
   table(['上界','累计数量','与前一桶相减得到的区间数量'],[
    ['100ms','850','≤100ms：850'],['300ms','975','(100,300]ms：125'],['1000ms','995','(300,1000]ms：20'],['+Inf','1000','>1000ms：5']
   ])+p('业务时限恰为300毫秒时，直接读取975/1000=97.5%在时限内、25次超过目标。阈值落在桶边界，达标数不需假设桶内分布。这份分母只有成功请求，若要判断全部请求的好率，还要补齐失败结果并按事先规定分类。',
   'p99目标秩为990，落在(300,1000]毫秒桶。只知该桶20个样本，无法知道第990个原始值。按经典桶均匀分布假设作线性插值，估计为300+(990−975)/(995−975)×700=825毫秒。估计误差受桶宽影响；在关注区域增加边界可以提高分辨率，也增加时间序列。',
   '程序通常从启动开始累计桶。查询最近5分钟，应逐桶序列取rate或窗口增量，处理重置后按相同上界le合并，再求比例或分位数。Prometheus指标常以秒为单位，300ms要对应0.3秒，不能与le="300"混用。SLO章promtool对照的0.99秒来自它自己的A/B桶输入，不是本节825毫秒的复算。'),

   p('标签给指标附加有限的分类，方便从整体缩小到某一类请求。Prometheus中一个指标名加一组不同标签值就是一条时间序列；标签组合数量称为基数。它决定需要采集、保存和查询多少独立数值。',
   '设12个路由模板、4种结果、3个部署版本、8个实例，所有组合都出现时，有12×4×3×8=1152组。经典直方图有8个有限上界，加+Inf、count和sum共11条序列，每组合11条，总计12672条。实际组合可能少于上界；实例替换与版本发布又会在保留期中留下历史序列。',
   '路由应使用/orders/{id}这种模板，而非每个订单的完整地址。订单号每次变化都可能创建新序列，最终使遥测本身占满资源。具体请求ID适合放入受权限与保留期管理的日志、追踪，在指标发现异常切片后再定位个体。租户标签也要按真实数量、变化率与排障价值决定。',
   '标签还影响能否解释结果。按瞬时实例名分组可能看不出慢请求始终属于同一发布版本；按版本分组又可能掩盖区域差异。保留能够检验具体假设的有界维度，并核对聚合时哪些标签被消去，避免用不断加标签补救不清楚的请求定义。')+linkRow(l[4]),

   p('现在沿一条独立的320毫秒订单请求展开跨度。为便于手算，所有时刻使用同一条教学时间轴：入口0..320ms，应用10..310ms；库存调用30..130ms，物流调用40..270ms。应用必须等两者完成，再在270ms以后组装结果。父跨度包含子操作，父子关系记录所属工作；是否必须等待，还由调用依赖决定。')+
   figure('v71-sre-parallel-spans',1120,720,'同一320ms订单请求的并行跨度：库存与物流重叠90ms，子区间并集240ms；物流在270ms完成，决定本次汇合时间。')+
   p('库存持续100ms，物流230ms，相加330ms。两者重叠[40,130]共90ms，区间并集为330−90=240ms，正好覆盖[30,270]。端到端为320ms，剩余80ms在这些子跨度之外；应继续拆解入口、应用和返回阶段，不能把子调用总和当作用户等待。',
   '关键路径是依赖关系中挡住本次结果完成的路径。本例物流较晚结束，决定270ms的汇合点；固定其他条件，把物流缩短20ms，汇合可提前20ms，单独把库存缩短20ms则不会改变汇合时刻。若物流230ms中有170ms等线程、40ms执行、20ms传输，应先解释线程为什么不可用。最长跨度若是发出后无需等待的异步工作，就未必决定当前响应。',
   '真实追踪跨进程时，用trace-id关联，span-id和parent-id连接操作；异步关系还可能使用span link。各主机绝对时钟可能有偏差，优先用本地单调计时得到持续时间，再结合发送、接收与依赖关系。上下文丢失、漏埋点或采样都可能让子跨度缺失，缺一段记录不能证明该调用没发生。')+linkRow(l[5]),

   p('观测管道也会丢事件、误分类或断关联。用可识别的受控请求覆盖成功、失败和超时，再分别核对客户端结果、入口计数、内部尝试与数据库事件。一项用户操作若进行了三次尝试，用户分母应保留一次，尝试账本保留三次；取消发生在客户端而服务仍在执行时，两端应各记录自己看见的事实。',
   '采样只保留部分追踪。头部采样在请求开始时决定是否保留，若每条独立保留1%，6个失败都未留下trace的概率为0.99⁶≈94.1%。没有失败样本十分常见，不能据采样条数算全量失败率。用覆盖全量、经过对账的计数器描述范围，再用保留的路径解释个体。',
   '尾部采样等到已收到的跨度显示结果后再决定是否保留，可优先保存错误或慢路径；但它需要暂存空间、等待完整路径的时间以及跨节点汇合，超时或缺跨度仍会影响判断。记录采样策略、丢弃计数和采集心跳，才能解释图中空白。',
   '修复后重发最初的查询，核对用户结果、入口分母、连接等待与路径是否共同改善。若只是把超时改归到被过滤类别，曲线会变好而用户仍在失败。首词元到达与整个推理完成也有不同起止边界，可沿同样的方法分别定义。')+linkRow(l[6]),

   p('用本章各自固定的材料作独立核对：RED账本的990+10次请求得到6/1000=0.6%失败；成功请求直方图得到975/1000=97.5%在300ms内；100条精确时长的全局最近秩p99为10ms，局部p99的加权值19.9ms不能替代它。三个答案的分母不同，解答中应分别写明。',
   '320ms请求中，库存和物流子区间合计330ms、并集240ms，物流决定汇合时间。当前候选是物流分支中的线程等待。若同口径慢请求根本未走该分支，或时序显示它没有阻塞响应，就应否定这个解释；先检查请求身份、依赖和样本选择，再考虑其他原因。',
   '这份题共十分：整体失败率、300ms达标率、分布合并解释、关键路径判断、能推翻假设的观察各两分。要求给出数值所对应的对象和窗口，使另一位读者能沿材料复算。'),

   p('最后把上下文传播与计时接到真实HTTP。telemetry_lab.py在本机启动API和backend两个服务，依次发送正常、注入等待、API直接503三次请求。正常路径是客户端→API→backend→API→客户端；503在API内返回，没有backend调用，因此3个用户请求对应3个API跨度、2个backend跨度。这个程序是独立输入，不执行前面的订单并行分支。',
   '每次客户端生成一个trace-id和父身份。API沿用trace-id并生成自己的span-id，调用backend时将该API span-id放入traceparent的parent-id位置；backend再生成自己的span-id，并把收到的父身份记录下来。源码逐条核对同trace、API接收到的客户端父身份、backend指向API的父身份。字段连接证明本次记录关联一致。')+c[8][0]+
   table(['实际执行位置','固定注入或身份条件','历史记录中核对什么'],[
    ['正常API与backend','短暂sleep和真实HTTP往返','API时长6.126ms，结果good'],
    ['慢API与backend','API前20ms、backend等待180ms/处理60ms、API后30ms','API实测299.793ms；backend实测180.213ms与65.025ms'],
    ['API直接503','失败分支不调用backend','API时长0.021ms；bad请求仍进入总数'],
    ['指标与父子身份','指标标签仅route/outcome；逐请求身份留在记录中','3请求、1坏、2backend跨度，父子断言通过']
   ])+p('慢路径固定注入相加为290ms；实测299.793ms与之相差9.793ms，包含sleep调度偏差、HTTP往返、序列化及其他未拆分开销，不能把残差全部判作网络时间。客户端另有10ms发起前等待，发生在API计时开始之前，API时长不包含它。单调时钟记录同进程持续时间，不把两台机器绝对时间戳相减来猜传输。')+
   fold('查看完整HTTP计时与trace传播源码',c[8][1])+
   p('这里的等待和处理均以sleep注入，是墙钟延迟，未测CPU计算。程序直接实现最小version-00 traceparent解析与父子字段断言，不使用OpenTelemetry SDK，没有验证完整标准兼容性、采样导出或生产负载。历史结果保留原始实测值，重新运行时毫秒数会变化；请求数、失败数和身份关系才是固定验收项。')+linkRow(l[8])
  ];
  finish(a,old,bodies,24);
  a.updated='2026.11.11';
  a.sections[6][1]+='<h3 id="collector-sampling-check">同一批追踪，经过两条采集管道</h3>'+
   p('OpenTelemetry Collector 是独立运行的采集程序。接收器读取应用发来的记录，处理器可筛选记录，导出器将剩余记录写到目标。实验把同一个接收器接到两条管道。一条直接写出，另一条等一段时间，把同一追踪的跨度聚在一起，再按错误状态选择整条追踪。',
   '判断观测链有无漏报时，先对比同一批输入的全量导出与采样导出，再对照业务账本。全量导出说明本次接收器看到了什么。账本回答用户任务是否完成、接收方到底写了几次。若任务最后成功、某次尝试却失败，采样可能保留这条轨迹，失败尝试与失败任务必须分开计数。'+
   '<a href="/article/agent-observability/#native-tail-sampling-ledger">沿真实 Collector 的两份导出复算 →</a>');
 }

 {
  const a=articles.find(x=>x.id==='incident');
  if(!a)throw Error('V71 missing incident chapter');
  same('incident section identities',a.sections.map(s=>s[0]),['先规定分母、窗口和可接受结果','先看结果，保留两个竞争解释','选一项能改变判断的探测','沿第201个请求，把560毫秒逐段算清','把排队增长还原成容量算术','保留功能，只改变占用区间','用相同触发条件复测，并解释剩余差值','运行程序，交一页能追问的结论']);
  const old=a.sections.map(s=>s[1]),c=old.map(codes),f=old.map(figures),l=old.map(links);
  same('incident code inventory',c.map(x=>x.length),[0,0,0,0,0,1,0,2]);
  const bodies=[
   p('查询的正常路径是：请求到达应用，借到数据库连接，执行用SQL语言表达的数据库查询，归还连接，再完成应用处理并返回结果。连接池保存一组可重复使用的连接；同一连接一次只交给一个请求。借不到连接的请求在池外等待，已经归还连接的请求则可以继续处理，不再占用这个位置。',
   '固定一份可复算材料：同一版本、同一租户的1000个请求，第一个在0ms到达，以后每10ms一个；4个独占连接，按到达顺序等待。正常SQL固定20ms，归还后应用处理10ms，无超时和重试。输入强度是100次/秒；空闲连接足够时，单请求端到端20+10=30ms。',
   '接着增加必须保留的30ms外部等待。要诊断的变化是：它在持有连接时发生，还是在归还后发生。这两种安排都保留同一功能，却会改变连接多久才能交给下一请求。所有数值都是整数事件模型的输入与推导，没有真实SQL或线上计时。',
   '统计分别保留t=10000ms的状态快照与1000个请求全部结束后的延迟分布。快照问此刻还有谁在等或执行；整批p95将全部时长排序，取最近秩ceil(0.95×1000)=950项。只取10秒前已完成的请求会漏掉仍在排队的慢请求，改变分母。'),

   p('先观察两组可由相同故障现象支持的解释。H1认为SQL从20ms变成50ms；H2认为SQL仍20ms，但拿到连接后多等外部动作30ms。二者的连接占用时间都是50ms，连接池交给后续请求的时间也相同。前端延迟因此可能完全相同。')+
   table(['同一到达序列下的组','每次持连接','整批p95','10秒完成 / 未完成'],[
    ['正常基线','20ms','30ms','998 / 2'],['待诊断故障材料','50ms','2430ms','796 / 204'],['H1：SQL为50ms','50ms','2430ms','796 / 204'],['H2：持连接外等30ms，再SQL20ms','50ms','2430ms','796 / 204']
   ])+f[1][0]+p('图中两条故障曲线逐请求重合。增加同口径p99或平均延迟，只会从相同分布读另一个数值，不能区分这两个解释。假设应给出各自不同的预测：H1需要SQL执行区间50ms；H2需要SQL执行20ms、持有期间另有30ms非SQL区间。',
   '现场若用户损害还在扩大，可先按已验证的兼容路径回切或限制新增工作，同时保存版本、流量与时序证据。恢复服务与查清原因可以并行；止损后的流量变化也要记录，否则会把负载下降误判成修复有效。'),

   p('选择同一请求的四个边界：获得连接、SQL开始、SQL结束、归还连接。连接持有区间是从获得到归还；SQL区间只覆盖执行查询。两者相减，能定位持有期间的非SQL时间。取不同请求的两段平均值相减，无法得到某个请求的真实路径。')+
   table(['本题探测','H1预测','H2预测','故障材料揭示'],[
    ['SQL执行区间','50ms','20ms','20ms'],['连接持有区间','50ms','50ms','50ms'],['持有期间非SQL区间','0ms','30ms','先外部等待30ms，再执行SQL']
   ])+p('这份区间来自同一条模拟时间轴，结果支持H2，并推翻“材料中的SQL执行为50ms”。它把原因缩小到外部等待占住连接这个安排；外部动作本身为什么需要30ms，仍是题设，不是已测出的远端故障。',
   '在真实服务中，用本地单调时钟记录这些边界，关联请求身份与连接租借身份，再核对埋点含义。数据库客户端span可能包含驱动排队，慢日志可能只含数据库执行；二者名称都写SQL也未必是同一区间。应抽查快慢请求，继续拆解远端调用、建连或锁等待，保留能推翻当前解释的证据。'),

   p('以第201个请求为具体对象。编号从1开始，因此它在(201−1)×10=2000ms到达。故障组前面的请求仍在轮流占用4个连接，它直到2500ms才拿到连接。随后外等30ms、执行SQL20ms，2550ms归还，最后处理10ms。')+f[3][0]+
   table(['同一请求的边界','模型绝对时刻','从前一边界经过'],[
    ['到达','2000ms','起点'],['获得连接','2500ms','池外等待500ms'],['SQL开始','2530ms','持连接外等30ms'],['SQL结束并归还','2550ms','SQL执行20ms'],['响应完成','2560ms','释放后处理10ms']
   ])+p('总等待2560−2000=560ms，也等于500+30+20+10。四段互不重叠、覆盖整个请求；500ms已经包含在560ms中，不能再把它加到端到端数值上。另一请求的跨度、不同进程的未校准绝对时刻，都不能填入这张表。',
   'SQL仍只需20ms，所以只查SQL慢日志可能找不到前端560ms的主体。许多请求在等连接时，CPU也可能不高；这是机制上的可能解释。本模型没有CPU实测，不能据此宣布已排除真实系统的CPU问题。'),

   p('资源能力取决于位置数与占用时间。故障组每连接持有50ms=0.05s，每个位置理想上限1/0.05=20次/秒；4个位置合计80次/秒。请求以100次/秒到达，持续输入超过上限20次/秒，等待因而累积。只把SQL的20ms当作占用，会误算成200次/秒并漏掉故障。',
   '10000ms时1000个请求已经全部到达。模型约定恰在该时刻发生的释放与完成已结算；应按四种互斥状态核对同一批请求。')+
   table(['故障快照状态','数量','判定边界'],[
    ['已经完成','796','完成时刻≤10000ms'],['已到达、尚未获得连接','199','到达≤10000ms&lt;获得连接'],['正在持有连接','4','获得≤10000ms&lt;归还'],['归还后仍在处理','1','归还≤10000ms&lt;完成']
   ])+p('796+199+4+1=1000，未完成204=199+4+1。它们只有199个在池外排队，不能把204全叫队列长度。最后一个到12540ms才完成；整批p95=2430ms应在这批排空后计算，10秒快照的完成数是另一种观察。',
   '80次/秒是假定固定占用、4个位置持续可用时的能力上界，有限批次的边界与释放后处理还会影响快照。实际扩池也可能把压力推到数据库CPU、锁或存储；增加等待线程并不增加连接服务率。先缩短已定位的不必要占用，再检查下游可承受的并发。'),

   p('本题外部等待与数据库事务无依赖，允许先归还连接再等待。干预只移动这30ms的位置：SQL仍20ms，外部动作仍30ms，释放后应用处理仍10ms。保留功能后，持有时间回到20ms，4个连接的理想能力4/0.02=200次/秒，高于原100次/秒输入。')+c[5][0]+
   p('由于这份固定到达序列不再需要等连接，每请求端到端为20+30+10=60ms。它比故障快，但比没有外部功能的30ms基线多30ms，这正是保留功能的代价。把外部等待删掉得到30ms，会改变题目要求。',
   '移动区间需要业务条件成立。若外部动作依赖尚未提交的数据，或与数据库写入必须协调，随意挪动可能破坏结果。事务发件箱outbox是一种安排：把业务变更与待发事件写在同一本地事务中，再由后续发送者交付事件；它还需处理重复交付和结果确认。本题没有实现这个协议，只要求外部动作可脱离连接占用。',
   '真实变更先选可回切的小流量，保留版本、输入、变更时刻与回切条件。若必须先限流，应单独记录到达量变化；流量降到80次/秒以下也可能消除池等待，这与在100次/秒下缩短占用是两种干预。'),

   p('用相同1000个请求、10ms到达间隔、4连接复测，比较用户时长、连接状态和最后完成时刻。下面每列属于一次独立模型运行；修复列保留30ms外部功能。')+
   table(['同口径结果','基线','故障','修复'],[
    ['持连接时间','20ms','50ms','20ms'],['整批p95','30ms','2430ms','60ms'],['10秒池外等待','0','199','0'],['10秒已完成','998','796','995'],['10秒持有 / 归还后处理','1 / 1','4 / 1','1 / 4'],['最后完成','10020ms','12540ms','10050ms']
   ])+p('修复时995+0+1+4=1000，剩余5个都有明确位置。比基线少完成3个，是每请求多30ms功能等待造成的尾部差异；池外等待为0，不能将这5个未完成全部解释成故障队列。基线998+0+1+1也为1000。',
   '模型中60ms−30ms=30ms恰好等于保留的外部等待，没有未解释残差。真实复测若多出另一段时间，应继续核对边界、调度和依赖开销，不把模型预测直接当作实测。固定版本、租户、到达量和请求类型，才能判断变化是否来自干预，而非输入不同。',
   '恢复还应同时满足正确结果、错误率与下游负载要求，并处理原有积压。延迟改善说明措施改变了路径；因果判断还依赖之前区分H1/H2的同请求证据，以及相同负载下的复测。'),

   p('incident_model.py使用最早可用时间维护4个连接，逐请求计算获得、归还和完成事件。它没有按墙钟等待，而是计算整数毫秒；完整report保留每个请求的行，读者可独立排序重算p95、重分状态并核对第201个请求。')+c[7][0]+
   p('源码固定四组运行：正常基线、持连接外等、SQL变慢的竞争解释、等待移出占用区间。断言不仅检查摘要，还比较两故障组1000项延迟逐项相等；另检查560ms、2430ms、60ms和故障快照。运行会在当前目录写report.json，建议解压到独立目录，保留原报告作对照。')+
   fold('查看完整事件队列程序与断言',c[7][1])+linkRow(l[7].slice(0,2))+
   p('一页诊断结论应能沿证据被追问：输入与统计窗口是什么；H1/H2分别预测哪段不同；20ms SQL和30ms非SQL持有怎样改变判断；干预保留了什么功能；复测的用户时长与四类快照是否守恒。最后列出真实环境仍需核对的外部依赖与业务前提，而不是给模型附上生产唯一根因的结论。')+linkRow(l[7].slice(2))
  ];
  finish(a,old,bodies,20);
  a.sections[7][1]+=
   '<h3 id="incident-connection-lease">实测同样拿不到连接，等待发生在哪</h3>'+p(
   '把上面的千次请求模型缩成 A 和 B 两次实际查询。连接池只提供一个 SQLite 连接，A 和 B 分别读取固定的订单总数 42 和 37。先让 A 在某个边界停住，再提交 B。第一、二组都能看到 B 借不到连接，但要看 A 的阶段记录才能区分原因。')+
   trainingFigure('incident-connection-lease','SQL 遇锁和持连接等 HTTP 都使 B 等待。先归还连接再等 HTTP，B 在 A 收到回复前完成查询。')+
   p('第一组中，另一个 SQLite 连接以独占模式打开事务，阻止查询读取。A 已借到池里的连接，执行 <code>SELECT</code> 时遇到锁。独立探测连接也返回同样的锁错误。为让冲突直接可见，程序把等锁时间设为零，收到错误后等测试放行，再执行一次相同查询。',
   '第二组让 A 借到连接后发出 HTTP 请求，回环服务收到请求但暂缓回复，A 此时还没执行 <code>SELECT</code>。第三组把外部调用移到 <code>pool.put_nowait(connection)</code> 之后。HTTP 回复仍被暂缓，B 却已经借到连接并查完。')+
   table(['放行之前','A 的事件','B 的状态','池里空闲连接'],[
    ['SQL 遇锁','SELECT 已尝试并遇到锁','等连接','0'],
    ['持连接等外部响应','HTTP 已到达，SELECT 未开始','等连接','0'],
    ['归还连接后等外部响应','SELECT 已完成并归还，HTTP 已到达','已查询完成','1']
   ])+
   '<div class="code-block"><div class="code-head"><span>终端</span></div><pre><code>python3 -B incident_connection_lease.py</code></pre></div>'+
   '<p class="practice-links"><a href="labs/incident-connection-lease.zip" download>下载实验包 ↓</a><a href="labs/incident-connection-lease/incident_connection_lease.py" download>下载 Python 脚本 ↓</a><a href="labs/incident-connection-lease/validation.json" target="_blank" rel="noopener">查看运行记录 ↗</a></p>'+
   p('复跑时，先在 <code>events</code> 里找 A 的借连接、SQL、外部响应与归还，再核对 B 的借连接和完成位置。后两组各有一次外部请求，A 都收到回执 <code>external-a</code>，订单结果仍为 42 和 37。记录用事件顺序检验连接占用，前面的数学模型继续负责推导容量与尾延迟。')+
   '<p><a href="/article/concurrency-pools/#bounded-worker-queue">回看工作线程、排队与下游许可怎样分别占用 →</a></p>';
 }
})();

// Live scraping follows the existing rules fixture and its published inventory checks.
(()=>{
 const a=articles.find(item=>item.id==='slo');
 a.sections[7][1]+='<h3 id="live-prometheus-burn">让 Prometheus 实际抓取两条实例序列</h3>'+
  '<p>把上一节的固定序列换成两个本机 HTTP 指标端点。Prometheus 每秒抓取一次并求值一次。规则使用 6 秒短窗、16 秒长窗和 4 秒持续条件，便于在一次运行中看清变化。两窗沿用 99.9% 目标下的 1.44% 坏率阈值。指标端点按实验脚本增加计数，分别记录好请求与坏请求。</p>'+
  '<p>先让甲的计数器模拟重启后的归零。它的坏计数从 1000 变为 0，乙实例一直是 600。这一段没有新增坏请求。逐实例调用 <code>rate</code> 时，甲的计数器下降会按重启处理，乙的 600 留在原序列。先相加会得到 1600 → 600。再按整条序列重启补偿，就把乙留存的 600 算成新增坏请求。本次 6 秒窗的真实查询中，两种算法分别给出每秒 0 次和约 120 次坏请求。记录保存两次查询和四条抓取序列。</p>'+
  trainingFigure('prometheus-live-burn','上半图手算重启前后的原始增量，下半图沿真实求值状态观察告警。')+
  '<p>接下来，甲每批 100 个请求中有 40 个坏，乙每批 100 个全好，稳定坏率为 40÷200＝20%。随着故障样本进入两个窗口，Prometheus 先写出待确认状态 <code>pending</code>。规则持续成立 4 秒后，同一组标签进入触发状态 <code>firing</code>。可在原始 <code>ALERTS</code> 样本中对照求值时刻，区分窗口统计与状态等待。</p>'+
  '<p>恢复阶段两个端点继续增加好计数。6 秒窗的坏率归零时，16 秒窗仍有约 13.33% 的坏率，快速告警已经解除。把两个坏率和告警状态一起读，才能知道是哪条条件改变。这个实验验证本机抓取、计数器重置和规则状态，生产流量、通知投递和当班响应分别验收。</p>'+
  '<p class="practice-links"><a href="labs/prometheus-live-burn.zip" download>下载实跑包 ↓</a> · <a href="labs/prometheus-live-burn/README.md">运行步骤</a> · <a href="labs/prometheus-live-burn/validation.json">查看抓取样本与告警原始记录 ↗</a> · <a href="https://prometheus.io/docs/prometheus/latest/querying/functions/#rate">Prometheus 计数器函数 ↗</a> · <a href="https://prometheus.io/docs/prometheus/latest/configuration/alerting_rules/">告警状态规则 ↗</a></p>'+
  '<h3 id="alert-notification-handoff">规则已经触发，为什么还没收到通知</h3>'+
  '<p>双窗口实验里的 <code>GuideLiveFastBurn</code> 已进入 <code>firing</code>。从规则触发到收件，中间还有 Alertmanager。它接收告警，按标签分组并选择接收方。排查时分别查看规则、Alertmanager 和接收端。</p>'+
  '<ol><li>告警活跃时，在 Prometheus 查询 <code>/api/v1/alerts</code>，确认告警名、标签和 <code>state</code>。<code>firing</code> 表示这组标签的规则条件已持续满足。</li>'+
  '<li>在同一台 Prometheus 查询 <code>/api/v1/alertmanagers</code>。<code>activeAlertmanagers</code> 列出当前发现并保留的目标地址。找不到预期地址，先查配置和服务发现。地址在列表中时，继续检查是否发到了那里。</li>'+
  '<li>在对应的 Alertmanager 查询 <code>/api/v2/alerts</code>，对照告警名、标签和时段。发送前若改写了标签，就按发出的标签查。找不到活跃告警时，回到 Prometheus 查发送错误。找到后，先查 <code>silencedBy</code>（人为静默）和 <code>inhibitedBy</code>（因另一条告警而抑制），再看匹配的路由和接收方。最后查测试接收端的入站请求或值班平台的事件记录，确认是否送达。</li></ol>'+
  '<p>Prometheus 的 <code>for</code> 决定条件持续多久才触发。Alertmanager 的 <code>group_wait</code> 决定新分组的首条通知等多久。两段等待从不同事件开始计时。<a href="/article/slo/#alert-notification-record-check">用原始 API 响应和入站记录核对这条路径 →</a></p>'+
  '<details><summary>在测试环境用 curl 读取三个接口</summary><p>将 <code>PROM</code> 和 <code>AM</code> 设为测试环境中两个服务的基址。</p><p><code>curl -fsS "$PROM/api/v1/alerts"</code><br><code>curl -fsS "$PROM/api/v1/alertmanagers"</code><br><code>curl -fsS "$AM/api/v2/alerts"</code></p></details>'+
  '<p class="source-at"><a href="https://prometheus.io/docs/prometheus/latest/querying/api/#alerts">Prometheus 告警查询 ↗</a> · <a href="https://prometheus.io/docs/prometheus/latest/querying/api/#alertmanagers">Alertmanager 目标发现 ↗</a> · <a href="https://github.com/prometheus/alertmanager/blob/main/api/v2/openapi.yaml">Alertmanager 查询接口 ↗</a> · <a href="https://prometheus.io/docs/alerting/latest/configuration/#route">路由与分组等待 ↗</a></p>'+
  '<h3 id="native-alert-notification">实跑：三条告警都触发，收件端收到了什么</h3>'+
  '<p>另起一次本机实验，把双窗口表达式换成一个可以控制的 0 或 1。三条序列用 <code>case</code> 区分，都先变成 1。规则的 <code>for</code> 设为 1 秒，Prometheus 实际抓取并向 Alertmanager 发送三条告警。Alertmanager 按 <code>severity="teaching"</code> 匹配到 <code>/reports</code>，每个分组等 5 秒再发送首条通知。</p>'+
  trainingFigure('alert-notification','三条都进了 Alertmanager。提前恢复和静默分别留下不同的记录，接收端只收到 long 的触发与恢复。')+
  '<p>先看 <code>short</code>。Alertmanager 收到以后，程序就把输入恢复成 0。它在首发等待结束前从活跃列表消失，接收端没有这组请求。再看 <code>silenced</code>。程序提前建好静默，首发等待过去后，这条告警仍在列表中，<code>silencedBy</code> 仍能查到静默 ID。</p>'+
  '<p>最后看 <code>long</code>。收到触发通知后才把输入恢复成 0，接收端随后又收到恢复通知。原始 HTTP 请求体里的两条状态依次是 <code>firing</code> 和 <code>resolved</code>，都进入 <code>/reports</code>。默认路由 <code>/fallback</code> 没收到请求。先核对实际入站，再判断通知送达。</p>'+
  trainingCode('解压后把两个路径换成本机二进制','SHELL','python3 -B alert_notification.py \\\n  --prometheus /path/to/prometheus \\\n  --alertmanager /path/to/alertmanager \\\n  --output local-validation.json')+
  '<p>这次使用 macOS arm64 上的 Prometheus 3.5.0、Alertmanager 0.34.2 和本机 HTTP 接收端。复跑核对事件顺序，具体时刻会随求值和抓取对齐变化。外部值班渠道和高可用集群要单独测试。</p>'+
  '<p class="practice-links"><a href="/labs/alert-notification.zip" download>下载实验包 ↓</a> · <a href="/labs/alert-notification/README.md">复跑步骤 →</a> · <a href="/labs/alert-notification/validation.json">查看查询响应和原始收件 ↗</a></p>'+
  '<h3 id="alert-notification-record-check">按 case 把触发、路由和收件对起来</h3>'+
  '<p>看原始记录的相对时间。程序在 8478 ms 查询到 Alertmanager 已有三条告警，首条通知在 13455 ms 到达接收端，两次观测相差 4977 ms。<code>group_wait</code> 从分组收到第一条告警开始，而 <code>alertmanager_ingress.at_ms</code> 是查询时刻。读数可以用来排序，测首发等待还需要分组开始时的记录。</p>'+
  '<p>把下面的代码保存为 <code>check_notification.py</code>，和实验包中的 <code>validation.json</code> 放在一起，运行 <code>python3 -B check_notification.py validation.json</code>。程序先用 <code>case</code> 对齐规则和 Alertmanager 的标签，再从接收端请求体找每条告警，分开核对匹配的接收方与实际送达。</p>'+
  trainingCode('用标准库核对三条告警最后到哪一步','PYTHON',`import json
import sys
from pathlib import Path

record = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
firing = record["prometheus_firing"]["alerts"]
ingress = record["alertmanager_ingress"]["alerts"]
after_wait = {row["labels"]["case"]: row for row in record["after_group_wait"]["alerts"]}
assert "short" not in {row["labels"]["case"] for row in record["short_cleared"]["alerts"]}

received = {}
for event in record["receiver_events"]:
    for alert in event["payload"]["alerts"]:
        case = alert["labels"]["case"]
        assert alert["labels"] == ingress[case]["labels"]
        received.setdefault(case, []).append((event["path"], alert["status"]))

expected = {
    "short": ("absent", []),
    "silenced": ("suppressed", []),
    "long": ("active", [("/reports", "firing"), ("/reports", "resolved")]),
}
assert set(firing) == set(ingress) == set(expected)
for case, (expected_state, expected_receipts) in expected.items():
    assert firing[case]["state"] == "firing"
    assert firing[case]["labels"] == ingress[case]["labels"]
    assert ingress[case]["receivers"] == [{"name": "reports"}]
    status = after_wait.get(case, {}).get("status", {})
    state = status.get("state", "absent")
    if case == "silenced":
        assert record["silence_id"] in status["silencedBy"]
    receipts = received.get(case, [])
    assert (state, receipts) == (expected_state, expected_receipts)
    print(case, state, receipts)`)+
  '<p>同一规则的三条告警都进入 <code>firing</code>，Alertmanager 都选了 <code>reports</code>。首发等待后的快照里，<code>short</code> 已离开活跃列表，<code>silenced</code> 仍带本次静默 ID。只有 <code>long</code> 在收件记录里有触发与恢复两次入站。</p>';
 a.updated='2026.11.12';
})();


